/*******************************************************************************
 *  DQ_Framework_Config.sql
 *  Data Quality Framework – Step 4: Framework DDLs and Rule Loading
 *  Database : BANKING_DQ_DB
 *  Schema   : DQ_MONITORING
 ******************************************************************************/

USE DATABASE BANKING_DQ_DB;

-- =============================================================================
-- 0. CREATE DQ_MONITORING SCHEMA
-- =============================================================================
CREATE SCHEMA IF NOT EXISTS DQ_MONITORING;
USE SCHEMA DQ_MONITORING;

-- =============================================================================
-- 1. DQ_RULE_CONFIG — Store all data quality rules
-- =============================================================================
CREATE OR REPLACE TABLE DQ_RULE_CONFIG (
    RULE_ID          NUMBER AUTOINCREMENT START 1 INCREMENT 1,
    RULE_NAME        VARCHAR(500) NOT NULL,
    RULE_TYPE        VARCHAR(50) NOT NULL,
    FREQUENCY        VARCHAR(50) DEFAULT 'ON_DEMAND',
    CRITICALITY      VARCHAR(20) NOT NULL,
    DB_NAME          VARCHAR(500) NOT NULL,
    TABLE_NM         VARCHAR(500) NOT NULL,
    COLUMN_NM        VARCHAR(500),
    RULE_DESCRIPTION VARCHAR(2000),
    RULE_SQL         VARCHAR(10000) NOT NULL,
    THRESHOLD_VALUE  NUMBER DEFAULT 0,
    RULE_DIMENSION   VARIANT,  -- JSON array e.g. ["accuracy","completeness"]
    IS_ACTIVE        BOOLEAN DEFAULT TRUE,
    CREATED_AT       TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(),
    UPDATED_AT       TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
);

-- =============================================================================
-- 2. DQ_RUN_CONTROL — Track each execution run
-- =============================================================================
CREATE OR REPLACE TABLE DQ_RUN_CONTROL (
    RUN_ID             NUMBER AUTOINCREMENT START 1 INCREMENT 1,
    RULE_ID            NUMBER NOT NULL,
    RUN_START_TIME     TIMESTAMP_NTZ,
    RUN_END_TIME       TIMESTAMP_NTZ,
    RULE_EXEC_RESULT   VARCHAR(50),
    RULE_OUTPUT_VALUE  NUMBER,
    RUN_STATUS         VARCHAR(50) DEFAULT 'PENDING',
    TRIGGERED_BY       VARCHAR(200) DEFAULT 'MANUAL',
    ERROR_MESSAGE      VARCHAR(5000),
    CREATED_AT         TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP(),
    UPDATED_AT         TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
);

-- =============================================================================
-- 3. DQ_RULE_RESULTS — Store rule-level execution results
-- =============================================================================
CREATE OR REPLACE TABLE DQ_RULE_RESULTS (
    RESULT_ID           NUMBER AUTOINCREMENT START 1 INCREMENT 1,
    RUN_ID              NUMBER NOT NULL,
    RULE_ID             NUMBER NOT NULL,
    DB_NAME             VARCHAR(500),
    TABLE_NAME          VARCHAR(500),
    COLUMN_NAME         VARCHAR(500),
    RULE_NAME           VARCHAR(500),
    RULE_TYPE           VARCHAR(50),
    EXPECTED_VALUE      NUMBER DEFAULT 0,
    ACTUAL_VALUE        NUMBER,
    FAILED_RECORD_COUNT NUMBER,
    TOTAL_RECORD_COUNT  NUMBER,
    PASS_PERCENTAGE     FLOAT,
    RESULT_STATUS       VARCHAR(20),
    SEVERITY            VARCHAR(20),
    ERROR_SAMPLE_QUERY  VARCHAR(5000),
    EXECUTED_AT         TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
);

-- =============================================================================
-- 4. DQ_ERROR_RECORDS — Store detailed failed records or samples
-- =============================================================================
CREATE OR REPLACE TABLE DQ_ERROR_RECORDS (
    ERROR_ID             NUMBER AUTOINCREMENT START 1 INCREMENT 1,
    RUN_ID               NUMBER NOT NULL,
    RULE_ID              NUMBER NOT NULL,
    DB_NAME              VARCHAR(500),
    TABLE_NAME           VARCHAR(500),
    ERROR_RECORD_VARIANT VARIANT,
    ERROR_REASON         VARCHAR(2000),
    CREATED_AT           TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
);

-- =============================================================================
-- 5. DQ_ANOMALY_RESULTS — Store anomaly detection results
-- =============================================================================
CREATE OR REPLACE TABLE DQ_ANOMALY_RESULTS (
    ANOMALY_ID       NUMBER AUTOINCREMENT START 1 INCREMENT 1,
    RUN_ID           NUMBER NOT NULL,
    DATABASE_NAME    VARCHAR(500),
    SCHEMA_NAME      VARCHAR(500),
    TABLE_NAME       VARCHAR(500),
    METRIC_NAME      VARCHAR(500),
    CURRENT_VALUE    NUMBER,
    PREVIOUS_VALUE   NUMBER,
    BASELINE_AVG     FLOAT,
    BASELINE_STDDEV  FLOAT,
    ANOMALY_STATUS   VARCHAR(50),
    ANOMALY_REASON   VARCHAR(2000),
    DETECTED_AT      TIMESTAMP_NTZ DEFAULT CURRENT_TIMESTAMP()
);

-- =============================================================================
-- 6. LOAD RULES INTO DQ_RULE_CONFIG
-- =============================================================================

-- -------------------------------------------------------------------------
